\title{Join Superadditivity of the $\Ztwo$ Co-index of Free Simplicial Complexes}
\author{Aristotle}
\date{2026-07-13}

\begin{document}

\begin{abstract}
We develop a self-contained combinatorial theory of \emph{free $\Ztwo$-simplicial complexes}---abstract simplicial complexes equipped with a fixed-point-free, face-preserving involution---and study the behavior of their $\Ztwo$-\emph{co-index} under the \emph{join} operation. Modeling the topological spheres $S^n$ by the \emph{octahedral spheres} $\Oct(n)$ (boundaries of cross-polytopes), we define the co-index lower bound $\coind(K)\ge n$ to mean the existence of an equivariant simplicial map $\Oct(n)\to K$. Our main theorem is that this lower bound is \emph{join-superadditive}:
\[
\coind(K\join L)\;\ge\;\coind(K)+\coind(L)+1.
\]
The proof is constructive: the join is a bifunctor on free $\Ztwo$-complexes and equivariant simplicial maps, and we exhibit an explicit equivariant simplicial map $\Oct(m+n+1)\to\Oct(m)\join\Oct(n)$ realizing the classical join homeomorphism $S^{m+n+1}\cong S^m\join S^n$. As a corollary the octahedral spheres form a \emph{join-monoid}. Specializing to $L=S^0=\Oct(0)$ recovers the suspension law $\coind(SK)\ge\coind(K)+1$. We complement these results with the dimension bound $\dim(K\join L)\ge\dim(K)+\dim(L)+1$ and discuss the matching upper bound as the principal open problem.
\end{abstract}

\maketitle

\section{Introduction}

The Borsuk--Ulam theorem and its combinatorial descendants are governed by a single integer invariant of spaces with a free $\Ztwo$-action: the \emph{co-index}. Informally, the co-index of a symmetric space $K$ measures the largest sphere that admits an equivariant map into $K$. It bounds chromatic numbers of Kneser-type graphs, controls fair-division and mass-partition results, and packages topological obstructions as a comparison against the family of spheres.

This paper isolates and proves a clean algebraic law obeyed by the co-index under the \emph{join}, the fundamental operation that glues two spaces by filling in every segment between them. The join underlies $S^m\join S^n\cong S^{m+n+1}$, and one expects the co-index to inherit a corresponding additive law. We confirm the lower-bound half of this expectation, constructively.

\subsection*{Contributions}
\begin{enumerate}
  \item A self-contained model of free $\Ztwo$-complexes, equivariant simplicial maps, and their co-index (Section~\ref{sec:model}).
  \item The octahedral spheres $\Oct(n)$ as combinatorial models of $S^n$ (Section~\ref{sec:oct}).
  \item The join $K\join L$, proved to be a free $\Ztwo$-complex and a bifunctor (Section~\ref{sec:join}).
  \item An explicit equivariant simplicial map $\Oct(m+n+1)\to\Oct(m)\join\Oct(n)$ (Section~\ref{sec:split}).
  \item The main theorem, join superadditivity, and its corollaries including suspension (Section~\ref{sec:main}).
  \item The dimension bound $\dim(K\join L)\ge\dim(K)+\dim(L)+1$ (Section~\ref{sec:dim}).
  \item A discussion of the sharp equality and the maximal-excess program (Section~\ref{sec:disc}).
\end{enumerate}

\section{The model: free $\Ztwo$-complexes and their co-index}\label{sec:model}

\begin{definition}[Free $\Ztwo$-complex]
A \emph{free $\Ztwo$-simplicial complex} on a vertex type $V$ is a pair $K=(\alpha,\Face)$ where $\alpha:V\to V$ is an involution ($\alpha\circ\alpha=\mathrm{id}$) that is \emph{free} ($\alpha(v)\ne v$ for all $v$), and $\Face$ is a family of finite subsets of $V$ that is nonempty ($\varnothing\in\Face$), downward closed ($t\subseteq s\in\Face\Rightarrow t\in\Face$), and $\alpha$-invariant ($s\in\Face\Rightarrow\alpha(s)\in\Face$).
\end{definition}

Freeness is exactly what makes the co-index meaningful: a fixed point of $\alpha$ would permit a constant equivariant map and collapse all co-indices.

\begin{definition}[Equivariant simplicial map]
A \emph{$\Ztwo$-simplicial map} $f:K\to L$ is a vertex map $f:V_K\to V_L$ with $f(\alpha_K(v))=\alpha_L(f(v))$ for all $v$ (equivariance) and $s\in\Face_K\Rightarrow f(s)\in\Face_L$ (simpliciality).
\end{definition}

These maps compose and admit identities, so free $\Ztwo$-complexes form a category.

\begin{definition}[Co-index lower bound]
For a free $\Ztwo$-complex $K$,
\[
\coind(K)\ge n\;:\Longleftrightarrow\;\text{there exists an equivariant simplicial map }\Oct(n)\to K,
\]
where $\Oct(n)$ is the octahedral $n$-sphere (Definition~\ref{def:oct}). The co-index $\coind(K)$ is the supremum of all such $n$.
\end{definition}

\begin{remark}
This is the standard $\Ztwo$-co-index of topological combinatorics, phrased combinatorially. Since $\|\Oct(n)\|\cong S^n$ and equivariant simplicial maps realize to equivariant continuous maps, the combinatorial definition yields genuine co-index lower bounds.
\end{remark}

\section{Octahedral spheres}\label{sec:oct}

\begin{definition}[Octahedral $n$-sphere]\label{def:oct}
For $n\ge0$, $\Oct(n)$ is the free $\Ztwo$-complex on $V_n=\{0,\dots,n\}\times\{\true,\false\}$ with antipode $\alpha(i,b)=(i,\lnot b)$ and faces
\[
\Face_n=\bigl\{\,s\subseteq V_n:\forall i,\ \lnot((i,\true)\in s\wedge(i,\false)\in s)\,\bigr\},
\]
i.e.\ a set is a face iff it contains no antipodal pair.
\end{definition}

\begin{proposition}
$\Oct(n)$ is a free $\Ztwo$-complex.
\end{proposition}
\begin{proof}
$\alpha$ is an involution ($\lnot\lnot b=b$) and free ($\lnot b\ne b$). The empty set has no antipodal pair; subsets of pair-free sets are pair-free (downward closure); and $\alpha$ permutes each axis so preserves the pair-free condition ($\alpha$-invariance).
\end{proof}

Geometrically $\Oct(n)$ is the boundary of the $(n+1)$-cross-polytope, a triangulation of $S^n$ with $2(n+1)$ vertices; its maximal faces have $n+1$ vertices, so $\dim\Oct(n)=n$.

\begin{proposition}[Self co-index]\label{prop:self}
$\coind(\Oct(n))\ge n$.
\end{proposition}
\begin{proof}
The identity vertex map is equivariant and simplicial.
\end{proof}

\section{The join and its bifunctoriality}\label{sec:join}

\begin{definition}[Join]
Let $K$ (on $V$) and $L$ (on $W$) be free $\Ztwo$-complexes. The \emph{join} $K\join L$ is the free $\Ztwo$-complex on $V\sqcup W$ with antipode $\alpha_K\sqcup\alpha_L$ acting coordinatewise, and a finite $T\subseteq V\sqcup W$ is a face iff its $V$-part $T|_V$ is a face of $K$ \emph{and} its $W$-part $T|_W$ is a face of $L$:
\[
T\in\Face_{K\join L}\iff T|_V\in\Face_K\wedge T|_W\in\Face_L.
\]
There is no cross-constraint linking the two sides.
\end{definition}

\begin{proposition}
$K\join L$ is a free $\Ztwo$-complex.
\end{proposition}
\begin{proof}
Coordinatewise the antipode is an involution and free. The empty set restricts to $\varnothing$ on both sides. Restriction to each side is monotone, giving downward closure. The $V$- and $W$-parts of $\alpha_{K\join L}(T)$ are $\alpha_K(T|_V)$ and $\alpha_L(T|_W)$, both faces.
\end{proof}

\begin{theorem}[Join is a bifunctor]\label{thm:bifun}
Given equivariant simplicial maps $g:K\to K'$ and $h:L\to L'$, the coordinatewise map $g\sqcup h$ is an equivariant simplicial map $K\join L\to K'\join L'$; moreover $\mathrm{id}\sqcup\mathrm{id}=\mathrm{id}$ and $(g'\sqcup h')\circ(g\sqcup h)=(g'\circ g)\sqcup(h'\circ h)$.
\end{theorem}
\begin{proof}
Equivariance holds on each summand from equivariance of $g$ and $h$. The $V'$-part of $(g\sqcup h)(T)$ is $g(T|_V)\in\Face_{K'}$ and the $W'$-part is $h(T|_W)\in\Face_{L'}$, giving simpliciality. The functor laws are inherited from the disjoint-union map.
\end{proof}

\section{The combinatorial join homeomorphism $S^{m+n+1}\cong S^m\join S^n$}\label{sec:split}

\begin{definition}[Splitting map]
$\Oct(m+n+1)$ has axes $\{0,\dots,m+n+1\}$. Define $\varphi_{m,n}:V_{m+n+1}\to V_m\sqcup V_n$ by
\[
\varphi_{m,n}(i,b)=\begin{cases}\iota_{V_m}(i,b)&\text{if }i<m+1,\\[2pt]\iota_{V_n}(i-(m+1),\,b)&\text{if }i\ge m+1,\end{cases}
\]
carrying the sign $b$ unchanged and shipping the first $m+1$ axes to the $\Oct(m)$-side, the last $n+1$ to the $\Oct(n)$-side.
\end{definition}

\begin{theorem}[Splitting map is equivariant simplicial]\label{thm:split}
$\varphi_{m,n}$ is an equivariant simplicial map $\Oct(m+n+1)\to\Oct(m)\join\Oct(n)$.
\end{theorem}
\begin{proof}
\emph{Equivariance.} The antipode flips $b$ and fixes $i$; since $\varphi_{m,n}$ chooses its side using only $i$ and preserves $b$, it commutes with the antipode in both branches.

\emph{Simpliciality.} Let $s$ be pair-free. The $\Oct(m)$-part of $\varphi_{m,n}(s)$ gathers images with $i<m+1$; an antipodal pair there would come from $(i,\true),(i,\false)\in s$ at a common axis $i$, contradicting pair-freeness. The $\Oct(n)$-part gathers images with $i\ge m+1$, re-indexed by $j=i-(m+1)$; since this shift is injective, a conflict at $j$ forces one at $i=j+(m+1)$ in $s$, again impossible. Thus both parts are faces.
\end{proof}

\begin{corollary}[Octahedral join splitting]\label{cor:oct-split}
There is an equivariant simplicial map $\Oct(m+n+1)\to\Oct(m)\join\Oct(n)$, the combinatorial shadow of $S^{m+n+1}\cong S^m\join S^n$.
\end{corollary}

\section{Main theorem: join superadditivity}\label{sec:main}

\begin{theorem}[Join superadditivity]\label{thm:main}
If $\coind(K)\ge m$ and $\coind(L)\ge n$ then $\coind(K\join L)\ge m+n+1$; equivalently $\coind(K\join L)\ge\coind(K)+\coind(L)+1$.
\end{theorem}
\begin{proof}
There are equivariant simplicial maps $g:\Oct(m)\to K$ and $h:\Oct(n)\to L$. By Theorem~\ref{thm:bifun}, $g\join h:\Oct(m)\join\Oct(n)\to K\join L$ is equivariant simplicial. Composing with the splitting map of Corollary~\ref{cor:oct-split},
\[
\Oct(m+n+1)\xrightarrow{\varphi_{m,n}}\Oct(m)\join\Oct(n)\xrightarrow{g\join h}K\join L,
\]
yields an equivariant simplicial map witnessing $\coind(K\join L)\ge m+n+1$.
\end{proof}

\begin{corollary}[Octahedral tower is a join-monoid]
$\coind(\Oct(m)\join\Oct(n))\ge m+n+1$. With the dimension equality of Section~\ref{sec:dim} and $\coind\le\dim$, this realizes $\Oct(m)\join\Oct(n)\cong\Oct(m+n+1)$ up to co-index.
\end{corollary}
\begin{proof}
Apply Theorem~\ref{thm:main} with $K=\Oct(m)$, $L=\Oct(n)$ and Proposition~\ref{prop:self}.
\end{proof}

\subsection{Suspension as the special case $L=S^0$}

\begin{definition}[Suspension]
The \emph{suspension} of $K$ is $SK:=K\join\Oct(0)$, where $\Oct(0)=S^0$ is the two-point antipodal $0$-sphere.
\end{definition}

\begin{theorem}[Suspension raises co-index]
If $\coind(K)\ge m$ then $\coind(SK)\ge m+1$.
\end{theorem}
\begin{proof}
Take $L=\Oct(0)$, $n=0$ in Theorem~\ref{thm:main}; since $\coind(\Oct(0))\ge0$, we get $\coind(K\join\Oct(0))\ge m+1$.
\end{proof}

This recovers the constructive suspension jump: joining with $S^n$ raises the co-index by $n+1$, and suspension is the smallest case $n=0$.

\section{Dimension bookkeeping}\label{sec:dim}

Let $\dim(K)$ be one less than the largest number of vertices in a face.

\begin{lemma}[Faces combine]
If $s\in\Face_K$ and $t\in\Face_L$ then $\iota_V(s)\cup\iota_W(t)\in\Face_{K\join L}$.
\end{lemma}
\begin{proof}
Its $V$-part is $s$ and its $W$-part is $t$ (disjoint images), both faces; apply the join criterion.
\end{proof}

\begin{lemma}[Vertex counts add]
$|\iota_V(s)\cup\iota_W(t)|=|s|+|t|$.
\end{lemma}
\begin{proof}
$\iota_V,\iota_W$ are injective with disjoint images.
\end{proof}

\begin{corollary}[Join dimension bound]
$\dim(K\join L)\ge\dim(K)+\dim(L)+1$.
\end{corollary}
\begin{proof}
Combine top faces of $K$ and $L$: the union has $(\dim K+1)+(\dim L+1)$ vertices, hence dimension $\ge\dim K+\dim L+1$.
\end{proof}

For octahedral spheres this is an equality, $\dim(\Oct(m)\join\Oct(n))=m+n+1$, matching both the co-index bound and $S^m\join S^n\cong S^{m+n+1}$.

\section{Discussion and future work}\label{sec:disc}

\subsection{The sharp equality}
Theorem~\ref{thm:main} is the lower-bound half of the conjectural $\coind(K\join L)=\coind(K)+\coind(L)+1$. The difficulty concentrates in the matching upper bound, which cannot be witnessed by a map but requires an obstruction---naturally the $\Ztwo$-index or an equivariant cohomological class, both expected to be additive under joins. With the join bifunctor and connecting map established, this obstruction is the only missing ingredient.

\subsection{The octahedral-tower obstruction}
A key upper bound would show any equivariant simplicial map $\Oct(n)\to\Oct(k)$ forces $n\le k$, i.e.\ $\coind(\Oct(k))=k$ exactly. The base case is the combinatorial Borsuk--Ulam parity obstruction; the join splitting $\Oct(k)\cong\Oct(0)\join\Oct(k-1)$ suggests a one-step induction.

\subsection{The maximal-excess program}
With excess $\dim(K)-\coind(K)\ge0$, the suspension law and $\dim(SK)=\dim(K)+1$ show excess is non-increasing under suspension. The maximal-excess conjecture seeks, for every $d\ge2$ and $1\le c\le d$, a $d$-dimensional $K$ with $\coind(K)=c$ and $\coind(SK)=d+1$. The join provides a dimension dial independent of co-index, exactly the freedom needed to separate $c$ from $d$.

