"""Verify the octahedral join splitting Oct(m+n+1) -> Oct(m) * Oct(n)."""
from itertools import combinations
from typing import Tuple, FrozenSet, List

OctVertex = Tuple[int, bool]

def oct_faces(n: int) -> List[FrozenSet[OctVertex]]:
    verts = [(a, s) for a in range(n + 1) for s in (True, False)]
    faces = []
    for k in range(n + 2):
        for c in combinations(verts, k):
            axes_t = {a for a, s in c if s}
            axes_f = {a for a, s in c if not s}
            if axes_t.isdisjoint(axes_f):
                faces.append(frozenset(c))
    return faces

def split(m: int, n: int, p: OctVertex):
    a, s = p
    return ("L", (a, s)) if a < m + 1 else ("R", (a - (m + 1), s))

def is_join_face(m: int, n: int, image) -> bool:
    left = frozenset(u for t, u in image if t == "L")
    right = frozenset(u for t, u in image if t == "R")
    def pairfree(fs):
        at = {a for a, s in fs if s}
        af = {a for a, s in fs if not s}
        return at.isdisjoint(af)
    return pairfree(left) and pairfree(right)

def check(m: int, n: int) -> bool:
    for f in oct_faces(m + n + 1):
        img = frozenset(split(m, n, p) for p in f)
        if not is_join_face(m, n, img):
            return False
    return True

if __name__ == "__main__":
    for m in range(3):
        for n in range(3):
            print(f"Oct({m+n+1}) -> Oct({m})*Oct({n}): simplicial =", check(m, n))

"""Assemble a co-index witness for a chain of joins and check its validity."""
from itertools import combinations
from typing import Callable, List, Tuple

OctVertex = Tuple[int, bool]

def oct_faces(n: int):
    verts = [(a, s) for a in range(n + 1) for s in (True, False)]
    out = []
    for k in range(n + 2):
        for c in combinations(verts, k):
            at = {a for a, s in c if s}; af = {a for a, s in c if not s}
            if at.isdisjoint(af):
                out.append(frozenset(c))
    return out

def oct_alpha(p): a, s = p; return (a, not s)

def split_fun(m: int, n: int):
    def f(p):
        a, s = p
        return ("L", (a, s)) if a < m + 1 else ("R", (a - (m + 1), s))
    return f

def is_equivariant(f: Callable, dom_alpha, cod_alpha, verts) -> bool:
    return all(f(dom_alpha(v)) == cod_alpha(f(v)) for v in verts)

def join_alpha(x):
    t, u = x
    return (t, oct_alpha(u))

if __name__ == "__main__":
    m, n = 2, 1
    verts = [(a, s) for a in range(m + n + 2) for s in (True, False)]
    f = split_fun(m, n)
    print("equivariant:", is_equivariant(f, oct_alpha, join_alpha, verts))
    print(f"coind(Oct({m})*Oct({n})) >= {m + n + 1}")

